-- Migra los dossiers históricos de La Lectura a crm_lecturas.
--
-- Estas dos lecturas se aprobaron ANTES de que el webhook mandara el dossier
-- completo: en Hilván quedó solo el resumen en texto dentro de `notas`. El
-- JSON se recuperó desde el Supabase del sitio vía la función lectura_cache
-- (la misma que usa el sitio para no re-gastar tokens en una marca ya leída).
--
-- Idempotente: no inserta si ese prospecto ya tiene una lectura con dossier.

-- Javiera Correa Creación Consciente — pieza-ancla · Primavera
INSERT INTO public.crm_lecturas (prospecto_id, url, dossier, producto_derivado, fecha)
SELECT '46bbed2a-369b-405a-a963-bf06cad36509'::uuid, 'https://javieracorrea.com/', '{"logo":"https://nuevaconscienciafinanciera.com/wp-content/uploads/2021/08/ArmoniaF-Logo-Horizontal.png","brief":null,"triage":"calza","fuentes":[{"url":"https://javieracorrea.com/","tipo":"sitio","titulo":"Javiera Correa Creación Consciente"},{"url":"https://veronicacorrea.com/curso-transformacion-consciente-completo-gratis","tipo":"prensa","titulo":"Curso-transformacion-consciente-completo-gratis - Escuela Veronica Correa"},{"url":"https://www.javieracorrea.com/transforma-tu-vida/","tipo":"prensa","titulo":"Creación Consciente: Transforma tu Vida - Javiera Correa"},{"url":"https://revistaeyn.com/empresasymanagement/educar-para-el-futuro-pasa-por-formar-personas-conscientes-no-solo-profesionales-GC31443959","tipo":"prensa","titulo":"Borja Vilaseca propone una educación consciente para formar a los líderes del futuro"},{"url":"https://www.latercera.com/laboratoriodecontenidos/noticia/javiera-correa-la-felicidad-organizacional-va-mucho-mas-alla-de-tener-una-mesa-de-ping-pong/VINGD3PEUVG43HSPVA64FWGGRA/","tipo":"prensa","titulo":"Javiera Correa: “La felicidad organizacional va mucho más allá de tener una mesa de ping pong” - La Tercera"},{"url":"https://www.academia.cl/programa/curso-crear-para-cuidar-herramientas-expresivas-con-enfoque-arteterapeutico-para-el-bienestar-y-la-transformacion-social/","tipo":"prensa","titulo":"Curso Crear para cuidar: herramientas expresivas con enfoque arteterapéutico para el bienestar y la transformación social - Universidad Academia de Humanismo CristianoUniversidad Academia de Humanismo Cristiano"},{"url":"https://www.youtube.com/javieracorrea","tipo":"web","titulo":"Javiera Correa - YouTube"},{"url":"https://hotmart.com/product/diplomado-en-creacion-consciente-y-transformacion-personal-2/Q39179745F","tipo":"web","titulo":"Diplomado en Creación Consciente y Transformación Personal - Javiera Correa - learn a new skill - Online Courses and Subscription Services | Hotmart"}],"pruebas":{},"senales":{"url":"https://javieracorrea.com/","skus":0,"redes":["https://www.instagram.com/javiera.correa_/","https://www.youtube.com/javieracorrea"],"claims":[{"palabra":"calidad","contexto":", sin nuevas estrategias de venta o marketing ni sacrificar calidad de vida, mediante un sistema de transformación profunda de"},{"palabra":"única","contexto":"desarrollo personal y más de 15 años enseñando metodologías únicas, simples y efectivas. Más de 1500 personas han cursado nue"}],"titulo":"Javiera Correa Creación Consciente","paginas":["https://javieracorrea.com/","https://javieracorrea.com/contacto"],"precios":null,"densidadTu":0.0398,"plataforma":null,"tieneAbout":false,"descripcion":"Metodologías de transformación personal, diseño de vida consciente y trabajo de creencias.","densidadNosotros":0.004},"imagenes":["https://nuevaconscienciafinanciera.com/wp-content/uploads/2022/02/javiera-correa.png","https://images.cdn1.buscalibre.com/fit-in/180x180/27/cf/27cf562556fa41851ab65e781649f9f2.jpg","https://nuevaconscienciafinanciera.com/wp-content/uploads/2022/02/ana-jimenez.png","https://images.cdn2.buscalibre.com/fit-in/180x180/b7/f5/b7f5ff40d533d7eea9c58b2604112943.jpg","https://nuevaconscienciafinanciera.com/wp-content/uploads/2022/02/miquel-pino.png","https://nuevaconscienciafinanciera.com/wp-content/uploads/2022/02/violeta-zurcan.png"],"omitidos":[],"sintesis":{"vimos":[{"cita":"Llevo 20 años en el mundo del desarrollo personal y más de 15 años enseñando metodologías únicas, simples y efectivas. Más de 1500 personas han cursado nuestro en Diplomado Creación Consciente y Transformación Personal en más 8 países","observacion":"El trabajo duro ya está hecho: Javiera tiene 20 años de trayectoria, más de 1.500 personas formadas en 8 países, un libro publicado, audiolibro, podcast, diplomado y programas en vivo. Es una plataforma completa — no una promesa, una operación real."},{"cita":"Javiera Correa: \"La felicidad organizacional va mucho más allá de tener una mesa de ping pong\"","observacion":"Javiera aparece en La Tercera como experta en felicidad organizacional, lo que sugiere que su autoridad trasciende el espacio de desarrollo personal individual y tiene llegada al mundo corporativo y profesional — un territorio de mayor ticket y credibilidad externa."},{"cita":"Creación Consciente es recordar cómo ya creas tu realidad de forma natural y aprender a impactar en tu mundo externo de forma efectiva a través de alinear tu mundo interno y externo","observacion":"El canal de YouTube define la propuesta con una frase que es lo más ownable de toda la marca, pero vive enterrada en la descripción del canal, no en el hero del sitio."},{"cita":null,"observacion":"No hay página ''sobre mí'' estructurada visible en la navegación — siendo Javiera el diferenciador central, eso abre una brecha entre lo que vende y lo que muestra."}],"lectura":{"heroe":"Una persona funcional — profesional, adulta, que cumple con todo — que siente que hay un techo invisible que ella misma pone. No es que le falte esfuerzo ni inteligencia: es que algo adentro frena lo que afuera se propone. El problema interno es la sospecha de que el problema es ella, y que no sabe cómo cambiarlo sin volverse otra persona.","villano":"La categoría del desarrollo personal en español está llena de coaches que prometen lo mismo con palabras distintas: ''desbloquea tu potencial'', ''vive sin límites'', ''atrae lo que mereces''. El villano no es la competencia — es la indiferenciación del lenguaje. Cuando todo suena igual, la persona que de verdad necesita ayuda no sabe a quién creerle. Javiera tiene metodología real y trayectoria verificable; el riesgo es que su contenido se pierda en ese ruido si no muestra la diferencia con claridad.","vacaPurpura":"La frase del canal de YouTube: ''recordar cómo ya creas tu realidad de forma natural''. No es ''aprende a crear tu realidad'' — es recordar. Ese giro cambia todo: no te falta nada, ya lo tienes. Es la única promesa de la categoría que no implica que el cliente está roto. Eso, combinado con el nombre del libro — ''Merecer todo solo por el hecho de existir'' — forma un sistema de creencias coherente que ningún competidor directo está diciendo exactamente igual."},"esquemas":[{"id":"E2","cita":"Soy Javiera Correa ¡Bienvenida/o a la Creación Consciente!","notamos":"Javiera es la metodología: su nombre, su historia de 20 años y su certificación en neurolingüística son lo que diferencia esto de un curso genérico. Pero en la navegación del sitio no hay una sección ''sobre mí'' estructurada ni fotos suyas en contexto — solo un párrafo de bienvenida.","pregunta":"¿Estarías dispuesta a estar frente a cámara contando cómo llegaste a desarrollar esta metodología, o sientes que la marca funciona mejor cuando el foco está en el alumno y no en ti?","desbloquea":"Define si el contenido tiene vocería personal (Javiera como guía visible) o si el eje es el testimonio del alumno transformado. Esa decisión cambia el plan completo de producción.","porQueImporta":"En una categoría donde la credibilidad lo es todo, esconder al autor es dejarle el campo libre a cualquiera que sí aparezca en cámara. El rostro de Javiera no es vanidad — es el argumento principal."},{"id":"E5","cita":"Metodologías orientadas a conseguir: + Claridad de lo que deseas entendiendo porque. + Eliminar bloqueos subconscientes.","notamos":"La promesa emocional del sitio es profunda y transformadora — ''merecer todo solo por el hecho de existir'', ''alinear tu mundo interno y externo'' — pero el registro visual y el tono del sitio es funcional, casi informativo: menú, lista de módulos, formulario de contacto.","pregunta":"¿Qué debería sentir alguien en los primeros tres segundos de ver un video de Javiera Correa — antes de escuchar una palabra o leer un título?","desbloquea":"La dirección de tono, música, luz y ritmo de todo el contenido. Resuelve cuál es la emoción de entrada: calma, expansión, alivio, esperanza. Eso define la estética completa.","porQueImporta":"Hay una brecha entre lo que la marca promete sentir y lo que la marca hace sentir al primer contacto. Alguien que llega buscando transformación debería sentirla antes de comprar — y hoy el sitio no la transmite."}],"benchmark":{"similares":"Tara Brach (psicóloga y maestra de meditación): comparte tribu con Javiera porque su audiencia son profesionales adultos que funcionan bien en el mundo pero sienten que algo interno los limita — personas que buscan herramientas con respaldo y profundidad, no motivación superficial. Brené Brown (investigadora y autora): la tribu es la misma — adultos funcionales que quieren entender y trabajar sus patrones desde adentro, con una figura que combina autoridad académica y vulnerabilidad personal visible.","diferenciacion":"Javiera opera en un nicho más íntimo y boutique que cualquiera de las dos: grupos pequeños, metodología propia con nombre registrado, y una promesa que no parte del déficit (''te falta algo'') sino del reconocimiento (''ya lo tienes''). Ese giro — recordar en vez de aprender — es el contraste que la distingue dentro de esta compañía elevada."},"direccion":{"enfoque":"Un video de manifiesto protagonizado por Javiera — en cámara, en su voz — que articule el giro que hace su metodología única: no ''aprende a crear tu realidad'', sino ''recuerda que ya lo haces''. Una pieza que fundamente la diferencia antes de vender cualquier programa, y que le dé a toda la presencia digital un tono y una cara de referencia.","ocasion":{"id":"pv","cuando":"el próximo mes","nombre":"Primavera","porQue":"La entrada a primavera es el momento del año en que más personas sienten el impulso de cambiar algo en su vida — un trabajo, una relación, un patrón. Es la temporada natural de los propósitos de transformación, y calza con lo que Javiera enseña."},"productoTransicional":"pieza-ancla"},"tensiones":[{"detalle":"Javiera es el producto — su historia, su cara, su voz son lo irrepetible — pero el sitio y el contenido la tratan como firma, no como protagonista. Hay tensión entre una marca personal que depende de la persona y una presencia digital que la oculta.","esquemas":["E2"]},{"detalle":"La promesa es profunda y transformacional (''eliminar bloqueos subconscientes'', ''merecer todo solo por el hecho de existir''), pero el formato de entrada — texto plano, menú de cursos — es funcional e informativo. El continente no está a la altura del contenido.","esquemas":["E5","E9"]}]},"bloqueado":false}'::jsonb, 'pieza-ancla', '2026-08-04'::date
WHERE NOT EXISTS (
  SELECT 1 FROM public.crm_lecturas
  WHERE prospecto_id = '46bbed2a-369b-405a-a963-bf06cad36509'::uuid AND dossier IS NOT NULL
);

