SELECT 'daea421d-e461-4eae-a38d-0b79592c0b12'::uuid, 'https://dctestablished.cl/', '{"logo":"https://i.pinimg.com/originals/2f/f8/2b/2ff82b06f0d2b9174e03aa4af73a7f80.jpg","brief":null,"triage":"calza","fuentes":[{"url":"https://dctestablished.cl/","tipo":"sitio","titulo":"Ropa Urbana Juvenil - Poleras - Polerones Oversize\n – DCT Established"},{"url":"https://dctestablished.cl/blogs/ropa-urbana/guia-definitiva-del-poleron-oversize-en-chile","tipo":"prensa","titulo":"Guía polerón oversize en Chile – Cómo usarlo con estilo | DCT"},{"url":"https://dctestablished.cl/blogs/news/como-combinar-tu-poleron-oversize-con-estilo-urbano","tipo":"prensa","titulo":"Cómo combinar tu polerón oversize con estilo urbano | DCT – DCT Established"},{"url":"https://dctestablished.cl/blogs/ropa-urbana/moda-urbana-para-hombres-combina-polerones-oversize-con-estilo","tipo":"prensa","titulo":"Moda Urbana para Hombres: Combina Polerones Oversize con Estilo – DCT Established"},{"url":"https://www.falabella.com/falabella-cl/category/cat1320008/Moda-Hombre","tipo":"prensa","titulo":"Ropa Hombre | Hasta 50% DCTO | Falabella Chile"},{"url":"https://www.americanino.cl/americanino-cl/category/cat7500027/Polerones-hombre","tipo":"prensa","titulo":"Polerones hombre | Americanino"},{"url":"https://ezzetacompany.com/","tipo":"web","titulo":"EZZETA COMPANY | Ropa Oversize a nuestro estilo"},{"url":"https://ropamdf.cl/","tipo":"web","titulo":"MDF"}],"pruebas":{},"senales":{"url":"https://dctestablished.cl/","skus":1,"redes":["http://instagram.com/dctestablished","https://www.tiktok.com/@dctestablished","https://www.facebook.com/profile.php"],"claims":[{"palabra":"natural","contexto":"uello: Redondo, clásico y versátil. Manga: Corta, con caída natural. Diseño: Estampado frontal ''Freedom''. Origen: Diseño chilen"},{"palabra":"premium","contexto":"mos una marca de streetwear chilena que trabaja con algodón premium y diseños en edición limitada, pensados para quienes buscan"},{"palabra":"lujo","contexto":"DÓN PIMA GAMUZADA DISEÑO FREEDOM\" por su fusión perfecta de lujo, confort y estilo. Es más que una prenda; es una declaració"},{"palabra":"calidad","contexto":"ra ser L es un poquito chica pero a mi me quedó genial Gran calidad del algodón .. precioso diseño Es decir lo uso ahora al ata"},{"palabra":"exclusiv","contexto":"ana Descubre lo Último en Ropa Oversize Poleras & Polerones Exclusivos POLERA ALGODÓN PIMA GAMUZADA DISEÑO FREEDOM POLERA ALGODÓ"},{"palabra":"único","contexto":"ien gruesa lo cual da confianza que no se romperá fácil. Lo único que criticaría es que para ser L es un poquito chica pero a"}],"titulo":"Ropa Urbana Juvenil - Poleras - Polerones Oversize\n – DCT Established","paginas":["https://dctestablished.cl/","https://dctestablished.cl/pages/quienes-somos","https://dctestablished.cl/pages/contact","https://dctestablished.cl/products/polera-algodon-pima-gamuzada-diseno-freedom"],"precios":{"max":17990,"min":17990,"moneda":"CLP"},"densidadTu":0.0058,"plataforma":"shopify","tieneAbout":true,"descripcion":"Descubre poleras y polerones oversize, confeccionados en Chile con algodón peruano de alta calidad. Ediciones únicas y diseños exclusivos. ¡Paga en 3 cuotas precio contado y define tu estilo urbano! Envios a todo Chile !","densidadNosotros":0.0081},"imagenes":["https://dctestablished.cl/cdn/shop/articles/Oversize_Maitencillo.webp?v=1754091415&width=533","https://dctestablished.cl/cdn/shop/articles/La_Parva_d19385d3-8cf0-4076-a89c-8259e522e67e.webp?v=1755613427&width=533","https://dctestablished.cl/cdn/shop/files/Polerones_De_Verano_Trebol_Verde_Oscuro.webp?v=1745112212&width=533","https://dctestablished.cl/cdn/shop/files/Poleron_de_Verano_Diseno_Delantero_As_de_Picas_Verano_2024.webp?v=1745114472&width=533","https://dctestablished.cl/cdn/shop/files/Poleron_Algodon_Franela_Delantero_Diseno_Besos_Guinda_Otono_2025.webp?v=1744822236&width=533","https://dctestablished.cl/cdn/shop/files/Foto_Santi_9df4f76b-7220-46bc-be05-b51093caf852.jpg?v=1734296631&width=1100"],"omitidos":[],"sintesis":{"vimos":[{"cita":"El algodón es maravilloso La textura al vestir el poleron es una experiencia de comfort","observacion":"La fortaleza real de DCT ya está en boca de sus clientes: el algodón Pima gamuzado genera experiencias sensoriales que la gente describe con entusiasmo y que rara vez se ven en marcas de streetwear a este precio."},{"cita":"Hola, soy Magdalena Rodríguez, fundadora de DCT. Todo comenzó en 2024, cuando buscaba ropa cómoda y duradera para mis hijos adolescentes.","observacion":"Hay una historia de origen genuina y con cara: Magdalena Rodríguez fundó la marca en 2024 buscando ropa para sus hijos adolescentes y encontrando fallas de calidad en el mercado. Esa historia es propia y humana, pero vive enterrada en la página ''Quiénes somos'' y no aparece en ningún otro punto de contacto."},{"cita":"Elige la \"POLERA ALGODÓN PIMA GAMUZADA DISEÑO FREEDOM\" por su fusión perfecta de lujo, confort y estilo.","observacion":"El copy del sitio hace claims fuertes (''lujo'', ''calidad inigualable'') pero las palabras trabajan solas: no hay imagen ni video que muestre el material de cerca, el proceso de diseño ni la textura que los propios clientes elogian."},{"cita":"No seguimos tendencias, las creamos.","observacion":"La marca declara ''no seguimos tendencias, las creamos'', pero visualmente su estética oversize/streetwear es difícil de distinguir del estándar de la categoría: nombres de diseño genéricos (Freedom, Corona, Joker) y sin dirección fotográfica propia visible en el sitio."}],"lectura":{"heroe":"El joven urbano chileno que no quiere verse como todos, pero tampoco sabe bien cómo diferenciarse sin gastar una fortuna. Su problema interno no es ''no tener ropa'': es la incomodidad de sentir que su ropa no lo representa, que encaja demasiado, que lo que usa podría usarlo cualquiera. Lo que busca es autenticidad sin tener que explicarla.","villano":"El streetwear de fast fashion que promete actitud pero entrega tela delgada y diseños que se repiten en tres tiendas del mismo mall. El riesgo para DCT es caer en ese mismo territorio visual: si el contenido no muestra la diferencia táctil y de origen, la marca se lee igual que lo que critica.","vacaPurpura":"Magdalena diseñando para sus propios hijos adolescentes con algodón Pima gamuzado que sus clientes describen como ''una experiencia de confort''. No es ''hecho en Chile'' a secas: es una madre con nombre y cara que probó el producto en casa antes de venderlo, y un material que la gente toca y no olvida. Eso no lo dice ningún competidor visible en la categoría."},"esquemas":[{"id":"E2","cita":"Hola, soy Magdalena Rodríguez, fundadora de DCT. Todo comenzó en 2024, cuando buscaba ropa cómoda y duradera para mis hijos adolescentes.","notamos":"Magdalena Rodríguez tiene nombre, cara y una historia de origen con conflicto real: buscaba ropa para sus hijos y encontró un mercado que fallaba en calidad. Eso es material audiovisual de primer nivel. Pero en el sitio no hay ninguna foto ni video de ella, y la historia aparece solo en texto en una página secundaria.","pregunta":"¿Estarías dispuesta a aparecer frente a cámara contando cómo empezó DCT, o sientes que la marca habla mejor sin tu rostro?","desbloquea":"Define si el contenido tiene vocería personal (más irrepetible, más cercano) o es puramente de producto. Esa respuesta cambia el plan completo de producción.","porQueImporta":"En una marca chica y reciente, la fundadora es la diferencia irrepetible. Si Magdalena no aparece en cámara, DCT compite solo con su tela, y ahí el campo es muy parejo. Si aparece, la marca tiene algo que ninguna cadena puede copiar."},{"id":"E9","cita":"Es decir lo uso ahora al atardecer cdo refresca es muy muy cómodo y lo mejor ni lo sientes de lo suave que es","notamos":"Clientes reales describen el algodón Pima gamuzado con palabras como ''una experiencia de confort'' y ''ni lo sientes de lo suave que es'', pero no hay ningún contenido visual que muestre el material de cerca: sin macro, sin tacto, sin comparación. Los claims más fuertes del sitio trabajan solos, sin respaldo visual.","pregunta":"¿Qué detalle de tu algodón Pima, visto bien de cerca, le ganaría a cualquier texto que puedas escribir sobre él?","desbloquea":"La lista de planos macro y héroes de producto para la sesión. Convierte el claim sensorial en un plan de rodaje concreto.","porQueImporta":"La categoría streetwear se pelea visualmente. Si el diferencial real de DCT es táctil y sus competidores también dicen ''calidad premium'', el único camino para probarlo es mostrarlo a cinco centímetros: la fibra, el peso, la caída."}],"benchmark":{"similares":"Margo (México/Latinoamérica): marca de ropa fundada por una mujer, producción local, materiales con historia y foco en atemporalidad por sobre tendencia. Comparte tribu con DCT en que apunta a quien quiere vestirse con criterio propio, no seguir el ciclo rápido de la moda masiva. Es un peldaño aspiracional creíble para una marca chilena en etapa temprana.","diferenciacion":"DCT se mueve en streetwear urbano y oversize juvenil — territorio más callejero y menos editorial que Margo. Su nicho es más joven, más informal y más local (Chile como origen explícito), lo que le da un ángulo de pertenencia territorial que Margo no trabaja. El contraste es ese: Margo apunta a atemporalidad consciente, DCT apunta a identidad urbana chilena con calidad que sorprende."},"direccion":{"enfoque":"Una pieza corta protagonizada por Magdalena — o por jóvenes reales usando las prendas — que muestre en cámara la textura del algodón Pima y cuente, sin guión forzado, por qué esta ropa existe: el momento en que una madre buscó algo mejor y no lo encontró. Calza con el cambio de estación, cuando la gente renueva su ropa y busca algo que se sienta diferente desde el primer contacto.","ocasion":{"id":"pv","cuando":"En aproximadamente dos meses, al arrancar la temporada alta de moda.","nombre":"Primavera/Verano","porQue":"La temporada P/V es el momento natural para que una marca de ropa urbana defina su tono visual y presente sus colecciones: colores nuevos, más piel, más calle. Para DCT es la primera gran ocasión para aparecer con fuerza y mostrar en movimiento lo que sus clientes ya describen con tanto entusiasmo."},"productoTransicional":"contenido-temporada"},"tensiones":[{"detalle":"La marca dice ''no seguimos tendencias, las creamos'', pero su estética visual es indistinguible del streetwear masivo. La declaración choca directamente con lo que los ojos ven.","esquemas":["E5","E8"]},{"detalle":"El activo más poderoso de DCT es sensorial (la textura del algodón Pima gamuzado) y sus clientes lo confirman en sus reseñas, pero ningún contenido lo muestra. La promesa existe en palabras; la prueba, no.","esquemas":["E9","E4"]}]},"bloqueado":false}'::jsonb, 'contenido-temporada', '2026-07-20'::date
WHERE NOT EXISTS (
  SELECT 1 FROM public.crm_lecturas
  WHERE prospecto_id = 'daea421d-e461-4eae-a38d-0b79592c0b12'::uuid AND dossier IS NOT NULL
);

-- Verificación:
--   SELECT p.empresa, l.producto_derivado,
--          jsonb_array_length(l.dossier -> 'sintesis' -> 'vimos') AS vimos
--   FROM public.crm_lecturas l
--   JOIN public.prospectos p ON p.id = l.prospecto_id
--   WHERE l.dossier IS NOT NULL;
